15: import logger from './logger'
16: 
17: const entities = new Entities()
18: 
19: const globalWithSocketIO = global as typeof globalThis & {
20:   io: Server
21: }
22: 
23: export const solveIf = function (challenge: any, criteria: () => any, isRestore: boolean = false, isCheating = false) {
24:   if (notSolved(challenge) && criteria()) {
25:     solve(challenge, isRestore, isCheating)
26:   }
27: }
28: 
29: export const solve = async function (challenge: ChallengeModel, isRestore = false, isCheating = false) {
30:   challenge.solved = true
31:   const solvedChallenge = await challenge.save()
32: 
33:   logger.info(`${isRestore ? colors.grey('Restored') : colors.green('Solved')} ${solvedChallenge.difficulty}-star ${colors.cyan(solvedChallenge.key)} (${solvedChallenge.name})`)
34:   sendNotification(solvedChallenge, isRestore)
35:   if (!isRestore) {
36:     const cheatScore = antiCheat.calculateCheatScore(challenge, isCheating)
37:     const hintsAvailable = await HintModel.count({ where: { ChallengeId: solvedChallenge.id } })
38:     const hintsUnlocked = await HintModel.count({ where: { ChallengeId: solvedChallenge.id, unlocked: true } })
39:     if (process.env.SOLUTIONS_WEBHOOK) {
40:       webhook.notify(solvedChallenge, cheatScore, hintsAvailable, hintsUnlocked).catch((error: unknown) => {
41:         logger.error('Webhook notification failed: ' + colors.red(utils.getErrorMessage(error)))
42:       })
43:     }
44:   }
45: }
46: 
47: export const sendNotification = function (challenge: ChallengeModel, isRestore: boolean) {
48:   if (notSolved(challenge)) {
49:     return
50:   }
51: 
52:   const flag = utils.ctfFlag(challenge.name)
53: 
54:   const challengeKey = challenge.key as ChallengeKey
55:   const fullChallenge = challenges[challengeKey]
56: 
57:   let hasCodingChallenge = false
58:   if (fullChallenge) {
59:     hasCodingChallenge = Boolean(fullChallenge.hasCodingChallenge) ?? false
60:   }
61: 
62:   const notification = {
63:     key: challenge.key,
64:     name: challenge.name,
65:     challenge: challenge.name + ' (' + entities.decode(sanitizeHtml(challenge.description, { allowedTags: [], allowedAttributes: {} })) + ')',
66:     flag,
67:     hidden: !config.get('challenges.showSolvedNotifications'),
68:     isRestore,
69:     codingChallenge: config.get('challenges.codingChallengesEnabled') !== 'never' && hasCodingChallenge
70:   }
71:   const wasPreviouslyShown = notifications.some(({ key }) => key === challenge.key)
72:   notifications.push(notification)
73: 
74:   if (globalWithSocketIO.io && (isRestore || !wasPreviouslyShown)) {
75:     globalWithSocketIO.io.emit('challenge solved', notification)
76:   }
77: }
78: 
79: export const sendCodingChallengeNotification = function (challenge: { key: string, codingChallengeStatus: 0 | 1 | 2 }) {
80:   if (challenge.codingChallengeStatus > 0) {
81:     const notification = {
82:       key: challenge.key,
83:       codingChallengeStatus: challenge.codingChallengeStatus
84:     }
85:     if (globalWithSocketIO.io) {
86:       globalWithSocketIO.io.emit('code challenge solved', notification)
87:     }
88:   }
89: }
90: 
91: export const notSolved = (challenge: ChallengeModel) => challenge && !challenge.solved
92: 
93: export const findChallengeByName = (challengeName: string) => {
94:   for (const challenge of Object.values(challenges)) {
95:     if (challenge.name === challengeName) {
96:       return challenge
97:     }
98:   }
99:   logger.warn('Missing challenge with name: ' + challengeName)
100: }
101: 
102: export const findChallengeById = (challengeId: number) => {
103:   for (const challenge of Object.values(challenges)) {
104:     if (challenge.id === challengeId) {
105:       return challenge
106:     }
107:   }
108:   logger.warn('Missing challenge with id: ' + challengeId)
109: }
110: 
111: export const solveFindIt = async function (key: ChallengeKey, isRestore: boolean = false) {
112:   const solvedChallenge = challenges[key]
113:   await ChallengeModel.update({ codingChallengeStatus: 1 }, { where: { key, codingChallengeStatus: { [Op.lt]: 2 } } })
114:   logger.info(`${isRestore ? colors.grey('Restored') : colors.green('Solved')} 'Find It' phase of coding challenge ${colors.cyan(solvedChallenge.key)} (${solvedChallenge.name})`)
115:   if (!isRestore) {
116:     accuracy.storeFindItVerdict(solvedChallenge.key, true)
117:     accuracy.calculateFindItAccuracy(solvedChallenge.key)
118:     await antiCheat.calculateFindItCheatScore(solvedChallenge)
119:     sendCodingChallengeNotification({ key, codingChallengeStatus: 1 })
120:   }
121: }
122: 
123: export const solveFixIt = async function (key: ChallengeKey, isRestore: boolean = false) {
124:   const solvedChallenge = challenges[key]
125:   await ChallengeModel.update({ codingChallengeStatus: 2 }, { where: { key } })
126:   logger.info(`${isRestore ? colors.grey('Restored') : colors.green('Solved')} 'Fix It' phase of coding challenge ${colors.cyan(solvedChallenge.key)} (${solvedChallenge.name})`)
127:   if (!isRestore) {
128:     accuracy.storeFixItVerdict(solvedChallenge.key, true)
129:     accuracy.calculateFixItAccuracy(solvedChallenge.key)
130:     await antiCheat.calculateFixItCheatScore(solvedChallenge)
131:     sendCodingChallengeNotification({ key, codingChallengeStatus: 2 })
132:   }
133: }

